#!/usr/bin/env python3
import json,collections,html
from pathlib import Path
P=Path(__file__).resolve().parent;B=P.parent
pairs=[('businesses-dev1-proposal.json','business-import-dev1-20261104.json'),('businesses-dev1-supplement.json','business-supplement-dev1-20261104.json'),('businesses-dev1-rnt-expansion.json','business-rnt-expansion-dev1-20261104.json'),('businesses-dev1-coverage-expansion.json','business-coverage-expansion-dev1-20261104.json'),('businesses-dev1-final-expansion.json','business-final-expansion-dev1-20261104.json')];c=collections.defaultdict(collections.Counter);total=0
for pf,rf in pairs:
 ps=json.loads((B/pf).read_text());rs=json.loads((B/'evidence'/rf).read_text());d={(x['destination_slug'],x['business']['name']):x['business']['category_code'] for x in ps}
 for r in rs:
  if r['status']=='published_dev1':c[r['destination']][d[(r['destination'],r['name'])]]+=1;total+=1
osm=json.loads((P/'coverage.json').read_text());cats=['hospedaje','alimentacion','comercio','salud','servicios','vida-nocturna','cultura','experiencias','transporte','licores'];rows=''
for m in osm['municipalities']:
 s=m['destination_slug'];v=c[s];rows+='<tr><th><a href="http://localhost:8086/lugares/'+s+'/">'+html.escape(m['name'])+'</a></th><td>'+str(sum(v.values()))+'</td>'+''.join('<td>'+str(v[k])+'</td>' for k in cats)+'<td>'+str(m['located_candidates'])+'</td></tr>'
head=''.join('<th>'+html.escape(x)+'</th>' for x in cats);doc='<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Cobertura de comercios por lugar</title><style>body{font:16px system-ui;margin:30px;color:#173b2c;background:#f5f7f4}h1{font-size:30px}table{border-collapse:collapse;background:white}td,th{border-bottom:1px solid #ddd;padding:10px;text-align:left;font-size:14px}thead{background:#dceade}.scroll{overflow:auto}.note{background:#fff0cb;padding:15px}a{color:#1b6545}</style><h1>Cobertura de comercios por lugar</h1><p><strong>'+str(total)+' fichas públicas en dev1</strong>. Pulsa un municipio para abrir su página.</p><p class="note">Las fichas se basan en registros públicos y cartografía; no se afirma que los negocios estén reclamados ni que su operación actual haya sido confirmada. La última columna muestra candidatos de investigación, no negocios adicionales ya publicados. Puede incluir duplicados.</p><div class="scroll"><table><thead><tr><th>Municipio</th><th>En dev1</th>'+head+'<th>Candidatos de mapa</th></tr></thead><tbody>'+rows+'</tbody></table></div><p><a href="https://www.datos.gov.co/d/thwd-ivmp">Registro Nacional de Turismo</a> · Datos cartográficos © OpenStreetMap contributors</p></html>';(P/'cobertura-dev1.html').write_text(doc);(B/'evidence/business-coverage-dev1-20261104.json').write_text(json.dumps({k:dict(v) for k,v in sorted(c.items())},ensure_ascii=False,indent=2)+'\n');print(total, {s:dict(c[s]) for s in ['bello','caldas','envigado','la-estrella']})
